sys_variable_value.value:
(function() {
    var result = { valid: true, message: "" };

    if (!inputs || !inputs.managersysid || !inputs.basesysid) {
        result.valid = false;
        result.message = "Missing required inputs (managersysid or basesysid).";
        return result;
    }

    var baseGR = new GlideRecord('x_1834930_office_0_office_base');
    baseGR.addQuery('manager', inputs.managersysid);
    baseGR.addQuery('sys_id', '!=', inputs.basesysid);
    baseGR.query();

    if (baseGR.hasNext()) {
        result.valid = false;
        result.message = "This manager is already assigned to another base.";
        return result;
    }

    var funcGR = new GlideRecord('x_1834930_office_0_function');
    if (!funcGR.get('7b0c81b8c378721012482925990131f6')) {
    result.valid = false;
    result.message = "Function 'Office / Base Manager' not found.";
    return result;
}

    var regGR = new GlideRecord('x_1834930_office_0_base_registration');
    regGR.addQuery('base', inputs.basesysid);
    regGR.addQuery('user', inputs.managersysid);
    regGR.addQuery('function', funcGR.sys_id);
    regGR.query();

    if (regGR.hasNext()) {
        result.valid = false;
        result.message = "This manager is already registered to this base as Office / Base Manager.";
        return result;
    }

    result.functionsysid = funcGR.sys_id.toString();
    return result;
})();

